SELECT s1."c0" AS "id", s1."c1" AS "customer", s1."c2" AS "amount" FROM (SELECT s2."c0" AS "c0", s2."c1" AS "c1", s2."c2" AS "c2", ROW_NUMBER() OVER (ORDER BY s2."c2" DESC NULLS LAST, s2."c1" ASC NULLS LAST, s2."o" ASC NULLS LAST) AS "o" FROM (SELECT s3."c3" AS "c0", s3."c4" AS "c1", s3."c5" AS "c2", s3."o" AS "o" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1", s4."c2" AS "c2", s4."c0" AS "c3", s4."c1" AS "c4", s4."c2" AS "c5", s4."o" AS "o" FROM (SELECT "id" AS "c0", "customer" AS "c1", "amount" AS "c2", rowid AS "o" FROM "orders") AS s4) AS s3) AS s2) AS s1 ORDER BY s1."o" ASC NULLS LAST
